export function extraLabels(lang){const result=Object.fromEntries(X_KEYS.map((k,i)=>[k,(X_VALUES[lang]||X_VALUES.EN).split('|')[i]]));result.languageHint=({EN:'The recipe remains in your own words. Choose the output language next to each prompt and request a local translation when needed.',HU:'A recept a saját nyelveden megmarad. A kész prompt mellett válassz nyelvet, és szükség esetén kérj helyi fordítást.',DE:'Das Rezept bleibt unverändert. Die Sprache direkt am Prompt wählen und bei Bedarf lokal übersetzen.',FR:'La recette reste inchangée. Choisissez la langue près du prompt et demandez une traduction locale.',ES:'La receta se conserva. Elige el idioma junto al prompt y solicita traducción local.',IT:'La ricetta resta invariata. Scegli la lingua accanto al prompt e richiedi la traduzione locale.',PT:'A receita é preservada. Escolha o idioma junto ao prompt e peça tradução local.',PL:'Opis pozostaje niezmieniony. Wybierz język przy prompcie i poproś o lokalne tłumaczenie.'}[lang]||result.translationHint);return result;}
export function validateExtraLabels(){return Object.values(X_VALUES).every(s=>s.split('|').length===X_KEYS.length);}
